/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=file, operation=update
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Update an activity */
export type PipedriveV2FileUpdateParams = {
  resource: 'file';
  operation: 'update';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the file to update
 * @default 0
 */
    fileId?: number | Expression<number>;
/**
 * Update Fields
 * @default {}
 */
    updateFields?: {
    /** The updated visible name of the file
     */
    name?: string | Expression<string>;
    /** The updated description of the file
     */
    description?: string | Expression<string>;
  };
};

export type PipedriveV2FileUpdateOutput = {
  active_flag?: boolean;
  activity_id?: unknown;
  add_time?: string;
  cid?: unknown;
  deal_id?: number;
  deal_name?: string;
  description?: unknown;
  file_name?: string;
  file_size?: number;
  file_type?: string;
  id?: number;
  inline_flag?: boolean;
  lead_id?: unknown;
  lead_name?: unknown;
  log_id?: unknown;
  mail_message_id?: unknown;
  mail_template_id?: unknown;
  name?: string;
  org_id?: number;
  org_name?: string;
  person_id?: number;
  person_name?: string;
  product_id?: unknown;
  product_name?: unknown;
  remote_id?: string;
  remote_location?: string;
  s3_bucket?: unknown;
  update_time?: string;
  url?: string;
  user_id?: number;
};

export type PipedriveV2FileUpdateNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  config: NodeConfig<PipedriveV2FileUpdateParams> & { credentials?: Credentials };
  output?: Items<PipedriveV2FileUpdateOutput>;
};